import{_ as r,a0 as i,w as p,s as a,ao as s,I as e,x as u,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"如何在 Ubuntu 桌面中應用強調色 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 桌面中應用強調色 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 桌面中應用強調色 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 桌面中應用強調色 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220814 How to Apply Accent Colour in Ubuntu Desktop","title":"如何在 Ubuntu 桌面中應用強調色","tag":"202209","desc":""},"relativePath":"202209/20220814 How to Apply Accent Colour in Ubuntu Desktop.md","filePath":"[post].md"}'),b={name:"202209/20220814 How to Apply Accent Colour in Ubuntu Desktop.md"};function d(m,t,T,C,g,w){const l=i("Link");return p(),a("div",null,[t[15]||(t[15]=s('<h1 id="如何在-ubuntu-桌面中應用強調色" tabindex="-1">如何在 Ubuntu 桌面中應用強調色 <a class="header-anchor" href="#如何在-ubuntu-桌面中應用強調色" aria-label="Permalink to “如何在 Ubuntu 桌面中應用強調色”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/13/075753yoi4j2ozozkkxmmk.jpg" alt=""></p><blockquote><p>得益於開發者們最近的貢獻，在 Ubuntu 中使用自己的強調色是很簡單的。</p></blockquote><p>每個 Linux 發行版都有它們默認的主題，具有各自的主色調。強調色用於在各個設置中突出主色調。通常，主色調和強調色應該形成對比和補充。</p><p>在最近的 GNOME 桌面的更新之後，Ubuntu 桌面在 22.04 LTS 版本中引入了強調色。</p><p>儘管如何應用它們是顯而易見的，但是為了 Linux 的新手，我將解釋如何在 Ubuntu 桌面中使用強調色。</p><h3 id="在-ubuntu-桌面中應用強調色" tabindex="-1">在 Ubuntu 桌面中應用強調色 <a class="header-anchor" href="#在-ubuntu-桌面中應用強調色" aria-label="Permalink to “在 Ubuntu 桌面中應用強調色”">​</a></h3><ol><li>從應用菜單中打開 <ruby>系統設置<rt>System Settings</rt></ruby></li><li>進入 <ruby>外觀<rt>Appearance</rt></ruby> 菜單</li><li>在 <ruby>風格<rt>Style</rt></ruby> 菜單下，你應該見到一套預設的顏色。</li><li>選擇其中的一個來改變強調色。</li></ol><p>一旦更改，強調色將被應用到 GTK 應用程序中的選區和 GTK 控件中，如切換按鈕和文件夾的默認外觀。</p><p>默認的強調色是橙色，有十種顏色可供選擇，具體如下：</p><ul><li>橙色</li><li>樹皮色</li><li>鼠尾草色</li><li>橄欖綠</li><li>鉻綠</li><li>普魯士綠</li><li>藍色</li><li>紫色</li><li>品紅色</li><li>紅色</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/08/Accent-Colour-in-Ubuntu.jpg" alt="Accent Colour in Ubuntu"></p><p>（LCTT 譯註：樹皮色是一種棕色，鼠尾草色是一種灰綠色。）</p><p>你應該記住一點，深色和淺色的主題的強調色組合可能改變你的桌面的整體外觀。</p><p>以上的特性只是只適用於目前使用 GNOME 桌面的 Ubuntu，而不適用於其它提供原生 GNOME 的發行版，例如 Fedora Workstation。因為有一些內容是由 Ubuntu 團隊開發的，並且並沒有合併到 GNOME 上游。</p><h3 id="kubuntu-中的強調色" tabindex="-1">Kubuntu 中的強調色 <a class="header-anchor" href="#kubuntu-中的強調色" aria-label="Permalink to “Kubuntu 中的強調色”">​</a></h3><p>使用帶有 KDE Plasma 桌面的 Kubuntu，你可以簡單地使用強調色。KDE Plasma 提供了預設的顏色，也有自定義的顏色選擇器選項。另外，自 KDE Plasma 5.25 起，強調色可以根據壁紙來改變。</p><p>為了在 Kubuntu 中改變它，跟着下面的步驟走：</p><ul><li>在應用菜單中打開 <ruby>系統設置<rt>System Settings</rt></ruby></li><li>進入 <ruby>外觀<rt>Appearance</rt></ruby> &gt; <ruby>全局主題<rt>Global Theme</rt></ruby> &gt; <ruby>顏色<rt>Colours</rt></ruby> 標籤</li><li>選擇你的強調色</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/KDE-Plasma-5.25-Accent-Colour-Change-Based-on-wallpaper-1024x611.jpg" alt="KDE Plasma 5.25 - Accent Colour Change Based on wallpaper"></p><p>我知道 Lubuntu 與 Xubuntu 並沒有這個特性。而且它不太可能很快到來。</p><p>使用愉快。</p><hr>',23)),e("p",null,[t[1]||(t[1]=u("via: ",-1)),n(l,{href:"https://www.debugpoint.com/ubuntu-accent-colour/"},{default:o(()=>[...t[0]||(t[0]=[u("https://www.debugpoint.com/ubuntu-accent-colour/",-1)])]),_:1})]),e("p",null,[t[6]||(t[6]=u("作者：",-1)),n(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...t[2]||(t[2]=[u("Arindam",-1)])]),_:1}),t[7]||(t[7]=u(" 選題：",-1)),n(l,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[u("lkxed",-1)])]),_:1}),t[8]||(t[8]=u(" 譯者：",-1)),n(l,{href:"https://github.com/yjacks"},{default:o(()=>[...t[4]||(t[4]=[u("yjacks",-1)])]),_:1}),t[9]||(t[9]=u(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[u("wxy",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=u("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[u("LCTT",-1)])]),_:1}),t[13]||(t[13]=u(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[u("Linux中國",-1)])]),_:1}),t[14]||(t[14]=u(" 榮譽推出",-1))])])}const x=r(b,[["render",d]]);export{k as __pageData,x as default};
